import {petForm,FORM_LEVELS} from './pet-forms.js?v=13';
export function growthMarkup(v){const {kind,isMagic,defs,selected,owned,rank,q,cost,current,next,delta,art,bonuses,energy,testMode,catalog}=v,isPet=kind==='pet',form=isPet?petForm(selected.id,rank||1):null;
const tabs=`<div class="panelTabs growthTabs">${[['magicula','Magículas'],['pet','Pets'],['mount','Montarias']].map(([k,n])=>`<button data-growth-tab="${k}" class="${k===kind?'selected':''}">${n}</button>`).join('')}</div>`;
if(catalog)return `<div class="growthCompact">${tabs}<button class="textlink" id="growthCatalog">← Voltar ao equipado</button><div class="companionCards">${defs.map(d=>`<button data-companion-select="${d.id}">${art(d,'catalogue')}<b>${d.name}</b><small>${d.owned?'Nv'+d.rank:'Nv'+d.minLevel+' · '+d.cash.toLocaleString('pt-BR')+' cash'}</small></button>`).join('')}</div></div>`;
const nextText=rank>=100?'EVOLUÇÃO MÁXIMA':`NÍVEL ${rank} → ${rank+1}`,requirement=q.ok?`Personagem Nv${cost.level}+`:q.reason;
return `<div class="growthCompact">${tabs}<div class="growthDashboard"><section class="growthArt">${isMagic?`<span class="magicCore" style="--sx:${Math.min(5,Math.floor(rank/20))%4};--sy:${Math.floor(Math.min(5,Math.floor(rank/20))/4)}"></span><b>${energy.toLocaleString('pt-BR')} μ</b><button id="previewPressure" class="smallbtn" ${rank?'':'disabled'}>LIBERAR PODER</button>`:art(selected,'large',rank||1)}<span class="growthLevel">${rank}/100</span>${!isMagic?`<button class="textlink" id="growthCatalog">Trocar ${isPet?'pet':'montaria'} →</button>`:''}</section><section class="growthMain"><div class="growthHeading"><small>${isMagic?'PRESENÇA ESPIRITUAL':form?'FORMA '+(form.stage+1)+' / 6':'COMPANHEIRO'}</small><h3>${isMagic?'Magículas':form?.name||selected.name}</h3><b>${nextText}</b></div>${owned?`<div class="growthGain"><b>+${Math.max(0,delta).toLocaleString('pt-BR')} poder</b><span>AF ${current.af}→${next.af} · AM ${current.am}→${next.am}<br>HP ${current.hp}→${next.hp} · MP ${current.mp}→${next.mp}</span></div><div class="growthCostCompact">${rank>=100?'Nível100 atingido':`<b>${requirement}</b><span>Ouro: ${current.gold.toLocaleString('pt-BR')} / ${cost.gold.toLocaleString('pt-BR')}</span><span>${cost.material}: ${current.material.toLocaleString('pt-BR')} / ${cost.count.toLocaleString('pt-BR')}</span>`}</div><div class="growthDock"><button class="primary" id="growWithMaterials" ${!q.ok||q.missing||q.gold?'disabled':''}>${rank?'EVOLUIR':'DESPERTAR'}<small>Usar materiais</small></button><button class="smallbtn cashAction" id="growWithCash" ${!q.ok?'disabled':''}>${q.ok?q.price.toLocaleString('pt-BR')+' CASH':rank>=100?'MÁXIMO':'BLOQUEADO'}<small>Comprar faltantes + evoluir</small></button></div>`:`<p class="growthAcquire">Nv${selected.minLevel}+ · começa na forma1</p><div class="growthDock"><button class="primary" id="unlockGold">${selected.gold.toLocaleString('pt-BR')} OURO</button><button class="smallbtn cashAction" id="unlockCash">${selected.cash.toLocaleString('pt-BR')} CASH</button></div>`}${!isMagic&&owned?`<div class="growthEquip"><button class="smallbtn" id="equipCompanion">${selected.equipped?'DESEQUIPAR':'EQUIPAR'}</button>${kind==='mount'?'<button class="smallbtn" id="toggleMountPanel">MONTAR / DESMONTAR</button>':''}<small>${selected.equipped?'Bônus ativo':'Equipe para receber os atributos'}</small></div>`:''}</section></div><details class="growthExtra"><summary>Formas, atributos e regras</summary><p>${bonuses}</p>${isPet?`<div class="formGallery">${FORM_LEVELS.map((n,i)=>`<div class="formCard ${i===form.stage?'current':''}">${art(selected,'formPreview',n)}<b>Nv${n}</b></div>`).join('')}</div><p>${form.nextLevel?'Próxima transformação: Nv'+form.nextLevel+' · '+form.nextName:'Forma final atingida'}. A forma muda ao atingir a faixa; os atributos continuam crescendo a cada nível.</p>`:''}<p>${isMagic?'Liberar poder mostra ondas, plasma e partículas por3,2s; recarga20s. É uma demonstração de presença, sem dano extra ou medo oculto. Os atributos vêm do nível do núcleo.':'Um pet e uma montaria ativos por vez. Cada evolução usa os custos mostrados acima; formas não cobram uma compra adicional.'}</p><p>Materiais: caça, masmorras, chefes e suprimentos no Empório. Cash exige confirmação e preserva o requisito de nível.</p>${owned&&testMode?`<div class="magicLabControls"><label>LAB · nível<select id="magicLabRank" aria-label="Nível de evolução para testar">${[1,19,20,39,40,59,60,79,80,99,100].map(n=>`<option value="${n}" ${n===rank?'selected':''}>${n}</option>`).join('')}</select></label><button class="smallbtn" id="applyMagicLab">APLICAR NO PERSONAGEM</button></div>`:''}</details></div>`;}
